"use strict";(globalThis.webpackChunkgrc||=[]).push([[19183],{5984(e){e.exports=JSON.parse('{"citeKey":"liu2021studymodeling","slug":"liu-2021-study-modeling-1bdd","title":"A Study on Modeling and Optimization of Memory Systems","authors":["J. Liu","P. Espina","X.-H. Sun"],"venue":"Journal of Computer Science and Technology (JCST\'21), vol. 35, no. 1, January 2021","type":"Journal","entryType":"article","date":"January, 2021","year":2021,"era":"iit","month":1,"doi":"10.1007/s11390-021-0771-8","abstract":"Accesses Per Cycle (APC), Concurrent Average Memory Access Time (C-AMAT), and Layered Performance Matching (LPM) are three memory performance models that consider both data locality and memory assess concurrency. The APC model measures the throughput of a memory architecture and therefore reflects the quality of service (QoS) of a memory system. The C-AMAT model provides a recursive expression for the memory access delay and therefore can be used for identifying the potential bottlenecks in a memory hierarchy. The LPM method transforms a global memory system optimization into localized optimizations at each memory layer by matching the data access demands of the applications with the underlying memory system design. These three models have been proposed separately through prior efforts. This paper reexamines the three models under one coherent mathematical framework. More specifically, we present a new memory- centric view of data accesses. We divide the memory cycles at each memory layer into four distinct categories and use them to recursively define the memory access latency and concurrency along the memory hierarchy. This new perspective offers new insights with a clear formulation of the memory performance considering both locality and concurrency. Consequently, the performance model can be easily understood and applied in engineering practices. As such, the memory-centric approach helps establish a unified mathematical foundation for model-driven performance analysis and optimization of contemporary and future memory systems.","hasAbstract":true,"lede":"This paper reexamines the three models under one coherent mathematical framework.","links":{"pdf":"https://grc.iit.edu/papers/2021/liu-2021-study-modeling-1bdd.pdf"},"tags":["Performance Modeling","Performance Optimization","Memory Architecture","Memory Hierarchy","Concurrent Average Memory Access Time","Optimization of Memory Architectures"],"_projectIds":["optmem","ides"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["optmem","ides"],"memberAuthors":["sun-xian-he"],"funding":[{"agency":"NSF","award":"CCF-2008000","projectId":"optmem"},{"agency":"NSF","award":"CNS-1730488","projectId":"ides"},{"agency":"NSF","award":"CCF-2008907","projectId":"optmem"}]}')}}]);